class MemoryAllocator {
    static MemoryAllocator getInstance() {
        JEmalloc.init();
        return new MemoryAllocator();
    }
}
class MemoryUtil {
    static final Object ALLOCATOR;
    static {
        // Matching real MemoryUtil.<clinit> order: Library.initialize() first, then allocator
        ALLOCATOR = MemoryAllocator.getInstance();
    }
}
class JEmalloc {
    static void init() {
        // Real generated expression:
        Runtime.jemallocChosen = org.lwjgl.system.Pointer.BITS64 ? "jemalloc" : "jemalloc32";
        System.out.println("JEmalloc binding selected: " + Runtime.jemallocChosen);
        if (org.lwjgl.system.Pointer.BITS64 && !"jemalloc".equals(Runtime.jemallocChosen)) {
            throw new RuntimeException("Failed to load library: " + Runtime.jemallocChosen + ".dll (error code = 0)");
        }
    }
}

