            System.exit(1);
        }
        if (System.getProperty("os.arch").contains("64") && !org.lwjgl.system.Pointer.BITS64) {
            System.out.println("FAIL: BITS64 incorrect");
            System.exit(1);
        }
        System.out.println("SUCCESS: 64-bit JVM loads jemalloc (not jemalloc32)");
    }
}
